import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const PRACTICE_DISCLAIMER =
  'Educational clinical communication, OSCE preparation, ethics, and epidemiology/biostatistics principles only. Supervised clinical instruction is mandatory for real patient examination, diagnosis, or care.';

const PRACTICE_DISCLOSURE = {
  status: 'conceptual_diagram_only' as const,
  summary:
    'Delivered with structured OSCE communication & physical-exam checklists, worked 2×2 diagnostic sensitivity/specificity/PPV/NPV/NNT mathematical exercises, research study-design matrices, and four-pillar bioethics frameworks linked to CDC PH101 & Geeky Medics.',
};

function makePracticeChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  checklistOrMath: string,
  primaryReadKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'clinical_skills_public_health',
    chapterCode: `P${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['medical_foundations', 'clinical_applied', 'allied_health', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–5', unitOrModule: `Clinical Skills, Ethics & Community Medicine (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_uhs_mbbs', gradeOrYear: 'MBBS Community Med & OSCE', unitOrModule: `${chapterTitle}`, status: 'compulsory' },
      { frameworkId: 'hms_pathways', gradeOrYear: 'MD Practice of Medicine', unitOrModule: `Clinical Reasoning & Population Health (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Biostatistics, Study Design & Ethics (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Foundational organ anatomy (Domain A)', 'Physiological vital baselines (Domain E)'],
    learningObjectives: [
      `Execute the systematic communication, physical-examination sequence, or epidemiological method for ${chapterTitle.toLowerCase()}.`,
      `Apply explicit quantitative formulas or structured clinical checklists (${checklistOrMath}).`,
      `Evaluate ethical safeguards, bias traps, and patient-safety priorities under supervised learning standards.`,
    ],
    depthExplanations: {
      medical_foundations: `${mechanisms.join(' ')} Structured checklist / quantitative tool: ${checklistOrMath}.`,
      clinical_applied: `Bedside & population integration for ${chapterTitle.toLowerCase()}: ${clinical} (${PRACTICE_DISCLAIMER})`,
      allied_health: `Interprofessional vital-sign surveillance, sterile technique, communication safety (SBAR), and patient-centred education in ${chapterTitle.toLowerCase()}: ${checklistOrMath}`,
      graduate_research: `Biostatistical power/confounding control, diagnostic Bayesian likelihood ratios, clinical trial CONSORT standards, and IRB bioethics across ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: 'Core Method / Framework', definition: summary },
      { term: 'OSCE Checklist / Formula', definition: checklistOrMath },
      { term: 'Clinical & Safety Application', definition: clinical },
    ],
    keyFacts: [
      `Structured Checklist / Calculation Tool: ${checklistOrMath}.`,
      PRACTICE_DISCLAIMER,
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'High sensitivity (99%) means a positive screening result proves the patient definitely has the disease.', correction: 'PPV depends heavily on disease prevalence and specificity! In low-prevalence screening, even a 95%-specific test yields far more false positives than true positives (verify with Bayes / 2×2 table).' },
      { misconception: 'Informed consent is merely obtaining a signature on a legal hospital sheet.', correction: 'Valid informed consent is an active communicative dialogue confirming decision-making capacity, full disclosure of risks/benefits/alternatives, comprehension, and voluntary uncoerced choice.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} equips learners with reproducible examination frameworks, ethical reasoning, worked biostatistical calculations, and public-health safety habits requiring supervised clinical confirmation in real practice.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      checklistOrMath,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'human_anatomy', relation: 'Surface landmarks and nerve/vessel topography anchor inspection, palpation, percussion, and auscultation.' },
      { domainId: 'clinical_specialties', relation: 'Bedside skills and EBM trial appraisal guide specialist diagnostic and therapeutic workflows.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['structured_text', '2d_diagram', 'clinical_case'],
    diagram: {
      id: `diag-p${num}`,
      title: `${chapterTitle} — Systematic Method & Quality Safeguard`,
      kind: 'pathway',
      caption: `${summary} (${checklistOrMath})`,
      disclaimer: PRACTICE_DISCLAIMER,
      nodes: [
        { id: 'n1', label: 'Preparation & Pre-Condition', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'amber' },
        { id: 'n2', label: 'Structured Execution / Math', sublabel: checklistOrMath.slice(0, 62), tone: 'teal' },
        { id: 'n3', label: 'Synthesis & Safety Closure', sublabel: clinical.slice(0, 62), tone: 'blue' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Consent, hygiene & hypothesis framing' },
        { from: 'n2', to: 'n3', label: 'Accurate interpretation & team communication' },
      ],
    },
    assetDisclosure: PRACTICE_DISCLOSURE,
    activity: {
      title: `Structured OSCE Checklist / Quantitative 2×2 Exercise (${chapterTitle})`,
      kind: 'calculation',
      prompt: `Work cleanly through ${checklistOrMath} for ${chapterTitle}, verify zero safety or logical errors, and summarize your reasoning clearly.`,
      keyTakeaway: clinical,
    },
    readingKeys: [primaryReadKey, 'pmdc_mbbs_2024'],
    shortAnswers: [
      { id: `sa-p${num}-1`, prompt: `Outline the sequential checklist or methodological steps for ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: mechanisms.join(' '), level: 'medical_foundations' },
      { id: `sa-p${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB}.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'clinical_applied' },
      { id: `sa-p${num}-3`, prompt: `Apply ${checklistOrMath} to resolve an ethical, safety, or statistical failure mode in ${chapterTitle.toLowerCase()}.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-p${num}-1`,
      title: `OSCE / Public Health & EBM Worked Scenario: ${chapterTitle}`,
      scenario: `A teaching clinical-practice or public-health exercise requires applying ${checklistOrMath} within ${chapterTitle.toLowerCase()}.`,
      questions: ['Which structured framework or calculation governs the decision?', 'What safety, bias, or ethical safeguard prevents error?'],
      workedSolution: `${mechanisms[0]} Tool/Math: ${checklistOrMath}. Resolution: ${clinical}`,
      level: 'clinical_applied',
      disclaimer: PRACTICE_DISCLAIMER,
    },
    selfChecks: mcqs,
    educationalDisclaimer: PRACTICE_DISCLAIMER,
  };
}

